-- Disposable fixture only. Uses synthetic customers and never updates application customers.
IF DB_NAME() NOT LIKE 'Prosto_CRM_Page_Test[_]%' THROW 51999,'Disposable CRM page database required',1;
DECLARE @a int,@root int,@child int,@grandchild int,@download int,@b int,@itemA int,@itemB int,@stamp uniqueidentifier=NEWID(),@version binary(8),@accountVersion binary(8),@xml xml;
INSERT CRM_Accounts(Name_AR,Name_EN,AddedUser,Brand_ID) VALUES(N'عميل اختبار متعدد العلامات للدليل','Multi-brand guide test',1,1);SET @a=SCOPE_IDENTITY();
INSERT CRM_Account_Brands(Account_ID,Brand_ID,AddedUser) VALUES(@a,1,1);
INSERT Customer_Logins(AccountID,Username,PasswordHash,Salt,Iterations,ModifiedBy,SecurityStamp) VALUES(@a,CONCAT('multi-guide-',@a),CRYPT_GEN_RANDOM(32),CRYPT_GEN_RANDOM(32),210000,1,@stamp);
INSERT CRM_WorkGuide_Categories(Name_AR,Name_EN,Brand_ID,AddedUser) VALUES(N'جذر أول','First root',1,1);SET @root=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Categories(Parent_ID,Name_AR,Name_EN,Brand_ID,AddedUser) VALUES(@root,N'ابن أول','First child',1,1);SET @child=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Categories(Parent_ID,Name_AR,Name_EN,Brand_ID,AddedUser) VALUES(@child,N'حفيد أول','First grandchild',1,1);SET @grandchild=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Categories(Name_AR,Name_EN,Brand_ID,AddedUser) VALUES(N'تنزيل أول','First download',1,1);SET @download=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Categories(Name_AR,Name_EN,Brand_ID,AddedUser) VALUES(N'جذر ثان','Second root',2,1);SET @b=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Items(Name_AR,Name_EN,Summary_AR,Summary_EN,Details_AR,Details_EN,File_Url,File_Name,File_Extension,File_Size,Brand_ID,AddedUser) VALUES(N'دليل أول','First guide',N'ملخص','Summary',N'<p>نص أول</p>','<p>First text</p>','/FileManager/CRMWorkGuide/11111111111111111111111111111111.pdf','one.pdf','.pdf',10,1,1);SET @itemA=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_Items(Name_AR,Name_EN,Summary_AR,Summary_EN,Details_AR,Details_EN,File_Url,File_Name,File_Extension,File_Size,Brand_ID,AddedUser) VALUES(N'دليل ثان','Second guide',N'ملخص','Summary',N'<p>نص ثان</p>','<p>Second text</p>','/FileManager/CRMWorkGuide/22222222222222222222222222222222.docx','two.docx','.docx',10,2,1);SET @itemB=SCOPE_IDENTITY();
INSERT CRM_WorkGuide_ItemCategories(Item_ID,Category_ID,Brand_ID) VALUES(@itemA,@root,1),(@itemA,@child,1),(@itemA,@grandchild,1),(@itemA,@download,1),(@itemB,@b,2);
BEGIN TRY
 SET @xml=CONVERT(xml,CONCAT('<grants><grant id="',@b,'" view="1" download="1"/></grants>'));
 BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml;THROW 51999,'Unassigned brand category grant accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
 INSERT CRM_Account_Brands(Account_ID,Brand_ID,AddedUser) VALUES(@a,2,1);
 SET @xml=CONVERT(xml,CONCAT('<grants><grant id="',@root,'" view="1" download="0"/><grant id="',@download,'" view="0" download="1"/><grant id="',@grandchild,'" view="0" download="1"/><grant id="',@b,'" view="1" download="1"/></grants>'));
 BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 2,@a,@xml;THROW 51999,'Non-admin changed grants',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51200 THROW;END CATCH;
 SELECT @accountVersion=Row_Version FROM CRM_Accounts WHERE ID=@a;
 EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml,NULL,@accountVersion;
 SELECT @version=Row_Version FROM CRM_WorkGuide_AccessState WHERE Account_ID=@a;
 IF (SELECT COUNT(*) FROM CRM_WorkGuide_Access WHERE Account_ID=@a)<>4 THROW 51999,'Multibrand grants not saved exactly',1;
 DECLARE @list TABLE(ID int,Brand_ID int,Brand_Name nvarchar(max),Parent_ID int,Sort_Order int,Name_AR nvarchar(max),Name_EN nvarchar(max),Can_View bit,Can_Download bit,Item_Count int);
 INSERT @list EXEC Customer_WorkGuide_List @a,@stamp;
 IF (SELECT COUNT(DISTINCT Brand_ID) FROM @list)<>2 THROW 51999,'Union guide categories missing assigned brand',1;
 DECLARE @tree TABLE(ID int,Brand_ID int,Brand_Name nvarchar(max),Parent_ID int,Name_AR nvarchar(max),Name_EN nvarchar(max),Sort_Order int,Has_Access bit);
 INSERT @tree EXEC Customer_WorkGuide_Tree @a,@stamp;
 IF NOT EXISTS(SELECT 1 FROM @tree WHERE ID=@child AND Has_Access=0) OR NOT EXISTS(SELECT 1 FROM @tree WHERE ID=@grandchild AND Has_Access=1) THROW 51999,'Deep ancestor navigation or explicit grants incorrect',1;
 DELETE @list;INSERT @list EXEC Customer_WorkGuide_List @a,@stamp,NULL,0,2;
 IF EXISTS(SELECT 1 FROM @list WHERE Brand_ID<>2) OR NOT EXISTS(SELECT 1 FROM @list WHERE ID=@b) THROW 51999,'Guide brand filter incorrect',1;
 EXEC Customer_WorkGuide_File @a,@stamp,@itemA,@root,'details',0;
 EXEC Customer_WorkGuide_File @a,@stamp,@itemA,@download,'download',0;
 EXEC Customer_WorkGuide_File @a,@stamp,@itemB,@b,'details',0;
 BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@itemA,@root,'download',0;THROW 51999,'Rights combined across categories',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
 BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@itemA,@download,'details',0;THROW 51999,'Download grant implied text access',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
 BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@itemA,@child,'view',0;THROW 51999,'Parent grant inherited',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
 DELETE CRM_Account_Brands WHERE Account_ID=@a AND Brand_ID=2;
 BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@itemB,@b,'details',0;THROW 51999,'Removed membership retained file/details access',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
 BEGIN TRY EXEC Customer_WorkGuide_List @a,@stamp,@b;THROW 51999,'Removed membership retained category access',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
 DELETE @tree;INSERT @tree EXEC Customer_WorkGuide_Tree @a,@stamp;
 IF EXISTS(SELECT 1 FROM @tree WHERE Brand_ID=2) THROW 51999,'Removed membership leaked through navigation',1;
 INSERT CRM_Account_Brands(Account_ID,Brand_ID,AddedUser) VALUES(@a,2,1);
 UPDATE Brands SET IsActive=0 WHERE ID=2;
 BEGIN TRY EXEC Customer_WorkGuide_File @a,@stamp,@itemB,@b,'download',0;THROW 51999,'Inactive brand file accessible',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51912 THROW;END CATCH;
 DELETE @list;INSERT @list EXEC Customer_WorkGuide_List @a,@stamp;
 IF EXISTS(SELECT 1 FROM @list WHERE Brand_ID=2) THROW 51999,'Inactive brand listed',1;
 UPDATE Brands SET IsActive=1 WHERE ID=2;
 UPDATE CRM_Accounts SET Name_EN='Updated membership form version' WHERE ID=@a;
 BEGIN TRY EXEC CRM_Save_WorkGuide_Permissions 1,@a,@xml,@version,@accountVersion;THROW 51999,'Stale account form accepted',1;END TRY BEGIN CATCH IF ERROR_NUMBER()<>51201 THROW;END CATCH;
 SELECT @accountVersion=Row_Version FROM CRM_Accounts WHERE ID=@a;
 EXEC CRM_Save_WorkGuide_Permissions 1,@a,N'<grants/>',@version,@accountVersion;
 IF EXISTS(SELECT 1 FROM CRM_WorkGuide_Access WHERE Account_ID=@a) THROW 51999,'Grant replacement did not revoke all categories',1;
 IF NOT EXISTS(SELECT 1 FROM CRM_Activity_Logs WHERE Account_ID=@a AND Entity='WorkGuide_Permissions' AND Before_Data.exist('/row/Permissions/grant/Brand_ID')=1 AND After_Data.exist('/row/Permissions/grant')=0) THROW 51999,'Multibrand permission before/after audit absent',1;
END TRY
BEGIN CATCH
 UPDATE Brands SET IsActive=1 WHERE ID=2;
 THROW;
END CATCH;
DELETE Customer_Portal_Activity WHERE AccountID=@a;DELETE CRM_Activity_Logs WHERE Account_ID=@a;DELETE Customer_Logins WHERE AccountID=@a;DELETE CRM_WorkGuide_Access WHERE Account_ID=@a;DELETE CRM_WorkGuide_AccessState WHERE Account_ID=@a;
DELETE CRM_WorkGuide_ItemCategories WHERE Item_ID IN(@itemA,@itemB);DELETE CRM_WorkGuide_Items WHERE ID IN(@itemA,@itemB);DELETE CRM_WorkGuide_Categories WHERE ID=@grandchild;DELETE CRM_WorkGuide_Categories WHERE ID=@child;DELETE CRM_WorkGuide_Categories WHERE ID IN(@root,@download,@b);DELETE CRM_Account_Brands WHERE Account_ID=@a;DELETE CRM_Accounts WHERE ID=@a;
SELECT 'PASS multibrand explicit-category authorization, union/filter/tree, protected details/files, membership and active-brand revocation, stale forms and audit' Result;
